DO $$ BEGIN RAISE EXCEPTION 'PROBE2 %', (SELECT jsonb_build_object('in', count(*) FILTER (WHERE amount_in > 0), 'out', count(*) FILTER (WHERE amount_out > 0), 'zero', count(*) FILTER (WHERE amount_in = 0 AND amount_out = 0), 'older', (SELECT max(txn_date) FROM bank_transactions WHERE account='main' AND file_name <> 'Book3.xlsx'), 'vista_any', (SELECT max(txn_date) FROM bank_transactions WHERE description ~* 'vista')) FROM bank_transactions WHERE file_name = 'Book3.xlsx'); END $$;
